delete from public.content_references;

insert into public.content_references(
  source_key,opd_name,title,program_label,detail,key_facts,status,berani_program_id,
  reference_urls,source_label,sort_order
)
values
('gdoc-ref-2026-dinas-pendidikan','DINAS PENDIDIKAN','BERANI CERDAS','BERANI CERDAS','Perlu adanya testimoni anak-anak SMK dan guru yang dibantu biaya Prakerinnya mulai dari operasional hingga akomodasi dan transportasi, lewat Berani Cerdas.','Testimoni untuk siswa SMA kurang mampu yang dibantu seragam sekolahnya
Dan SLB yang dibantu sekolahnya lewat BOSDA','Siap Dibagikan',1,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',10),
('gdoc-ref-2026-diskominfosantik','DISKOMINFOSANTIK','Berani Berdering — Program Jaringan Satelit untuk Desa Blankspot','Berani Berdering','Program ini merupakan kebijakan strategis Pemerintah Provinsi Sulawesi Tengah untuk menghapus wilayah blankspot dan mempercepat transformasi digital secara inklusif di wilayah pedesaan.','Program bantuan jaringan satelit starlink untuk 150 desa blankspot (Zona Tanpa Sinyal) dan 10 Sekolah terpencil
Total Pagu Anggaran: Rp10,3 Miliar bersumber dari APBD Provinsi Sulawesi Tengah.
Total Sasaran: 150 Desa terpencil dengan kondisi geografis sulit dan keterbatasan infrastruktur telekomunikasi.
Alokasi per Desa: Rp69 Juta per desa penerima manfaat.
Skema Penyaluran: Dana dialokasikan melalui Badan Pengelola Keuangan dan Aset Daerah (BPKAD) dalam bentuk Bantuan Keuangan Khusus (BKK) yang langsung ditransfer ke Anggaran Pendapatan dan Belanja Desa (APBDes).
Dari total pagu Rp69 juta per desa, peruntukannya dibagi menjadi beberapa komponen utama
± Rp40 Juta: Digunakan untuk pengadaan infrastruktur fisik dan peralatan jaringan, seperti pembelian kabel fiber optik.
Sisa Anggaran (± Rp29 Juta): Dialokasikan untuk langganan/pembelian jaringan internet berbasis satelit serta penguatan kapasitas Sumber Daya Manusia (SDM) pengelola di desa.
Dengan Memanfaatkan teknologi berbasis satelit, termasuk Starlink, untuk memastikan konektivitas tetap stabil di area geografis yang sulit terjangkau kabel konvensional.
Kapasitas Akses: Setiap desa akan memiliki 1 jaringan utama yang dipancarkan ke 3 titik akses (access point).
Prioritas Konektivitas: Layanan internet diprioritaskan untuk memfasilitasi fasilitas publik desa, di antaranya:
Kantor Desa (mempercepat pelayanan pemerintahan).
Puskesmas Pembantu / Pustu (pelayanan kesehatan).
Sekolah (mendukung kebutuhan pendidikan digital).
Kabupaten Sigi: Mendapat jatah 15 desa.
Kabupaten Tojo Una-Una: Mendapat jatah 15 desa.
Kabupaten Lainnya: Masing-masing mendapatkan jatah 12 desa.','Siap Dibagikan',null,'["https://sulteng.antaranews.com/berita/390829/sulteng-alokasikan-anggaran-rp103-miliar-untuk-pemerataan-internet","https://palu.tribunnews.com/sulteng/192565/pemprov-sulteng-kucurkan-rp103-miliar-untuk-internet-150-desa-lewat-program-berani-berdering","https://www.instagram.com/p/DbCXl7rmByw/?utm_source=ig_web_button_share_sheet"]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',20),
('gdoc-ref-2026-dinas-sosial','DINAS SOSIAL','Pemutakhiran DTSEN melalui In-Depth Interview (IDI)','IN DEPTH INTERVIEW (IDI) · BERANI BERSINAR','Program In-Depth Interview (IDI) yang diselenggarakan oleh Dinas Sosial Provinsi Sulawesi Tengah, merupakan langkah strategis berbasis penelitian kualitatif untuk memperkuat akurasi Data Tunggal Sosial Ekonomi Nasional (DTSEN). Program ini diintegrasikan melalui inovasi aplikasi BERANI BERSINAR (Berantas Kemiskinan Terintegrasi, Bersih, Sinergi, Nyata, dan Responsif).','Program IN DEPTH INTERVIEW (IDI) Pemutakhiran DTSEN untuk Program Pengentasan Kemiskinan di Sulteng dan satu-satunya Provinsi di Indonesia yang melakukan pemutakhiran DTSEN.
Berbeda dengan survei kuantitatif biasa yang hanya mencatat angka atau status sarana fisik, metode IDI berfokus pada wawancara mendalam (tatap muka langsung secara individual) guna menggali akar masalah kemiskinan, tingkat kerentanan sosial, serta strategi bertahan hidup masyarakat miskin.
Pemutakhiran ini mengintegrasikan data dari berbagai instansi pendukung utama, yaitu Dinsos Provinsi Sulteng, Bappeda, Dinas PMD, Dukcapil, Inspektorat Provinsi, dan Badan Pusat Statistik (BPS).
Ditengah efisiensi anggaran In Depth Interview ini dilakukan di 4 Kabupaten/Kota, yaitu Kota Palu. Kabupaten Donggala, Kabupaten Parimo dan Kabupaten Morowali.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',30),
('gdoc-ref-2026-bappeda','BAPPEDA SULTENG','Pilot Project Program FASILITATOR BERANI MOMBANGU','FASILITATOR BERANI MOMBANGU','Program pemberdayaan masyarakat dan percepatan pengentasan kemiskinan serta penurunan stunting melalui penempatan tenaga fasilitator 50 orang di 50 desa/kelurahan yang terbagi di 5 Kecamatan, Kec Labuan, Tanantovea, Sindue, Banawa dan Banawa Tengah.','Validasi Data Kemiskinan: Menyelaraskan dan memperkuat data kemiskinan di tingkat desa dengan Data Tunggal Sosial Ekonomi Nasional (DTSEN) agar bantuan dari pemerintah tepat sasaran.
Pendekatan Sosial & Serap Aspirasi: Melakukan Focus Group Discussion (FGD) bersama warga, tokoh pemuda, dan pemerintah desa guna memetakan masalah serta potensi lokal.
Pengembangan Potensi Desa: Mengawal pengembangan Sumber Daya Manusia (SDM), Sumber Daya Alam (SDA), hingga legalitas potensi wisata di wilayah setempat.
Aksi Sosial & Kesehatan: Membantu pelayanan posyandu untuk menekan angka stunting, pengadaan apotek hidup, serta pengaktifan kembali organisasi kepemudaan.
Penanganan Anak Tidak Sekolah (ATS): Ikut serta mendukung program taktis dalam pencegahan dan pemerataan akses pendidikan di Sulawesi Tengah.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',40),
('gdoc-ref-2026-perpustakaan-kearsipan','DINAS PERPUSTAKAAN DAN KEARSIPAN','IPUSSULTENG','IPUSSULTENG','Perpustakaan berbasis digital dari Sulawesi Tengah bekerja sama dengan IPUSNAS.','Dinas meraih peringkat kedua nasional perpustakaan digital selama dua tahun berturut-turut.
Tingkat kegemaran membaca Sulawesi Tengah menempati peringkat ke-7 nasional. Aplikasi arsip Souraja telah didaftarkan ke Kemendagri.
Dinas merencanakan pengembangan arsip aset berbasis barcode, aplikasi mandiri perpustakaan, serta program Bunda Literasi.
Buku-buku yang tidak tersedia di IPUS Pusat, tapi tersedia di IPUS Sulteng.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',50),
('gdoc-ref-2026-disbunak','DINAS PERKEBUNAN DAN PETERNAKAN','Peningkatan Produktivitas Perkebunan dan Peternakan','Produktivitas & Hilirisasi','Program utama meliputi peningkatan produksi komoditas unggulan, penyediaan benih unggul, pupuk, mekanisasi pertanian, inseminasi buatan, pelayanan kesehatan hewan, serta peningkatan kapasitas petani dan peternak.','Hilirisasi diarahkan pada kakao, kelapa, kopi, dan komoditas peternakan melalui pengolahan produk, diversifikasi usaha, kemitraan dengan pasar modern, promosi, serta sertifikasi produk. Program hilirisasi 2026 mencakup 29.950 hektare, 20.872.000 bibit, dan 1.914 kelompok tani.
Nilai Tukar Petani perkebunan sampai Triwulan II 2026 sebesar 96,38, masih di bawah 100 sehingga perlu perhatian terhadap pendapatan dan biaya usaha petani. NTP peternakan mencapai 108,67.
Dinas mengembangkan aplikasi Sibunak, Si-Geper, dan sistem pendataan bantuan berbasis NIK, nama penerima, kelompok, lokasi, serta jumlah bantuan.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',60),
('gdoc-ref-2026-disperindag','DINAS PERINDUSTRIAN DAN PERDAGANGAN','Hilirisasi Komoditas Unggulan dan Penguatan IKM','Hilirisasi & IKM','Disperindag berperan dalam pembinaan industri, perdagangan, perlindungan konsumen, dan penguatan rantai pasok.','Fokus program meliputi hilirisasi komoditas kelapa, perikanan, dan durian.
Komoditas kelapa telah dikembangkan menjadi tepung, konsentrat, nata de coco, dan produk turunan lainnya.
Ekspor durian hingga Juni 2026 mencapai sekitar 7.000 ton. Pemerintah mendorong pengolahan durian menjadi pasta, permen, dan produk bernilai tambah.
Disperindag melakukan pengawasan ketersediaan LPG melalui koordinasi dengan kabupaten/kota, menggelar operasi pasar murah, serta menjaga pasokan bahan pokok. BPSK berperan menyelesaikan sengketa dan melindungi hak konsumen.
Fasilitasi HAKI dan sertifikasi halal ditargetkan mencapai 13.000 pelaku IKM. Program Sertifikasi Halal Gratis (SEHATI) telah terserap dan diusulkan mendapat tambahan kuota tahun 2027.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',70),
('gdoc-ref-2026-bpbd','BADAN PENANGGULANGAN BENCANA DAERAH','SIGANA — Sistem Informasi Tanggap Bencana','SIGANA','Memungkinkan masyarakat untuk melapor secara langsung dengan mengirimkan foto kejadian bencana yang ada di daerah SULTENG. agar BPBD bisa merespon dengan cepat dalam hal penganggulangan.','Integrasi Data Command Center: Seluruh data kebencanaan (contoh: data banjir) terintegrasi langsung dengan Command Center milik Pemerintah Provinsi Sulawesi Tengah dan dapat diakses secara langsung.
aplikasi tersedia di playstore','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',80),
('gdoc-ref-2026-bpsdm','BADAN PENGEMBANGAN SUMBER DAYA MANUSIA','Inovasi E-Learning & Anti Korupsi / Program ASN BELAJAR','ASN BELAJAR','Tersedia sistem pembelajaran mandiri (Learning Manajemen System) yang mencakup modul dan soal pemahaman anti korupsi yang diakhiri dengan evaluasi dan sertifikasi. BPSDM Provinsi Sulawesi Tengah mencatatkan diri sebagai satu-satunya di Indonesia yang memiliki inovasi program penyuluh anti korupsi, yang berjalan secara kolaboratif bersama praktisi dan ahli di tengah keterbatasan efisiensi anggaran. Saat ini fasilitas tersebut mampu menampung sekitar 200 peserta (termasuk perancangan Renstra di Bappeda).','Program ASN Belajar Dilaksanakan secara rutin setiap hari Jumat guna memastikan setiap ASN memahami tugas pokok dan fungsi (tupoksi) serta perannya masing-masing.
Pelatihan kepemimpinan berjenjang (seperti PIM I dan seterusnya) serta kompetensi manajerial diselenggarakan melalui metode tatap muka maupun daring (Zoom), mengingat pentingnya kapasitas ilmu bagi seorang pemimpin.
BPSDM telah mengantongi Akreditasi A secara mandiri untuk penyelenggaraan pendidikan dan pelatihan pengadaan barang dan jasa.','Siap Dibagikan',null,'[]'::jsonb,'INFORMASI & REFERENSI UNTUK PEMBUATAN KONTEN PROGRAM PEMPROV SULTENG 2026',90);

